const smartDetail0 = facts("gjensidigeHusSmart", [["service.smart.pris", "Hus Smart – veiledende alarmpris", "Veiledende alarmpris: Vann- og brannalarm 160 kr/mnd; vann-, brann- og innbruddsalarm 359 kr/mnd. Komponentene som følger med, leies og inngår i den månedlige prisen. Ingen bindingstid. Prisen for Tjenestene fremgår av den til enhver tid gjeldende avtalen. Alarmpris og forsikringspremie vurderes separat; egne oppsigelsesvilkår gjelder.", "Alarmtjenesten / Månedspris og leide komponenter; Fordeler / Ingen bindingstid", 1]])[0];
smartDetail0.qualificationSource = { ...facts("gjensidigeHusSmartTerms", [["service.smart.pris", "Hus Smart – veiledende alarmpris", "Veiledende alarmpris: Vann- og brannalarm 160 kr/mnd; vann-, brann- og innbruddsalarm 359 kr/mnd. Komponentene som følger med, leies og inngår i den månedlige prisen. Ingen bindingstid. Prisen for Tjenestene fremgår av den til enhver tid gjeldende avtalen. Alarmpris og forsikringspremie vurderes separat; egne oppsigelsesvilkår gjelder.", "12. Priser; 10. Varighet og oppsigelse", 1]])[0].source, note: "Kundens gjeldende avtale bestemmer faktisk tjenestepris; ingen bindingstid erstatter ikke egne oppsigelsesvilkår." };
smart.push(smartDetail0);
const smartDetail1 = facts("gjensidigeHusSmart", [["service.smart.installasjon", "Hus Smart – installasjon og leverandørbytte", "Kostnadsfri installasjon Vann-, brann- og innbruddsalarmen monteres av en installatør uten ekstra kostnad. Kjøper du vann- og brannalarm, kan du enkelt installere røykvarslere og vannsensor selv, og koble komponentene til alarmstasjonen ved hjelp av brukerveiledning og Smart alarm-appen. Ønsker du likevel å få installatør til å montere komponentene for deg, koster det 2 050 kroner. Du kan bestille montering ved å ringe oss på 915 03 100 . Kostnadsfri demontering og hjelp med oppsigelse av alarm fra annet selskap Hvis du allerede har alarm fra et annet selskap, kan vi demontere den og si opp avtalen kostnadsfritt. Du betaler ikke for alarmtjenesten under oppsigelsestiden med din gamle alarmleverandør, selv om vi har vært hos deg og installert den nye alarmen. Installasjonen er kostnadsfri. Kontakt oss på 915 03 100 om du ønsker demontering og hjelp med oppsigelse. Slik funker det: Etter du har kjøpt forsikringen, vil vår installasjonspartner Inselo kontakte deg for å avtale tidspunkt for demontering og installasjon. Installatør kommer hjem til deg og demonterer den gamle alarmen og installerer den nye alarmen kostnadsfritt. Alarmen vil fungere som den skal fra denne dagen. Vi tar ikke med den gamle alarmen. Du signerer en fullmakt som installatør har med seg, denne sender vi til alarmselskapet og sier opp din gamle avtale. Du begynner ikke å betale for den nye alarmen før oppsigelsestiden med det gamle alarmselskapet er over.", "Kostnadsfri installasjon; Kostnadsfri demontering og hjelp med oppsigelse av alarm fra annet selskap", 1]])[0];
smart.push(smartDetail1);
const smartDetail2 = facts("gjensidigeHusSmartTerms", [["service.smart.aktivering", "Hus Smart – aktivering og kundeplikter", "7. Kundens plikter Kunden forplikter seg til å bruke Utstyret og Tjenestene på riktig måte, og å informere alle brukere av Utstyret og Tjenestene om Utstyrets og Tjenestenes funksjoner og bruk. Kunden plikter å ta vare på Utstyret som eies av Selskapet og å ikke gjøre noe som kan ødelegge det. Kunden garanterer at Utstyret vil behandles og brukes i samsvar med Selskapets anvisninger og brukerveiledninger. Kunden bekrefter at hvis Selskapets brukerveiledninger ikke følges ved håndtering og bruk av Utstyret, kan dette påvirke driften av Utstyret og følgelig leveringen av Tjenestene. Selskapet er ikke ansvarlig for eventuelle feil i Tjenestene som skyldes at Kunden ikke har brukt Utstyret i samsvar med brukerveiledninger. Kunden må utføre Kontaktprosedyren før alarmsystemet aktiveres. Alarmtjenesten begynner først etter at Kontaktprosedyren er gjennomført, selv om Kunden allerede har blitt fakturert. Kunden garanterer at Kontaktprosedyren inneholder oppdaterte, korrekte og relevante opplysninger. Informasjonen som er gitt, kan oppdateres ved å kontakte Selskapet. Kunden skal gi Selskapet, eller en autorisert partner utpekt av det, tilgang til Installasjonsadressen for å oppfylle sine kontraktsforpliktelser. Kunden er ansvarlig for eventuelle tillatelser myndighetene måtte kreve for bruken av Utstyret. Kunden plikter å informere Selskapet uten unødig opphold om eventuelle feil, samt hvis Kunden mener eller mistenker at Utstyret eller deler av det ikke fungerer som avtalt eller trenger service. Kunden må også uten unødig opphold informere Selskapet om eventuelle endringer som kan påvirke leveringen av Tjenestene, for eksempel endring av kontaktpersoner, deres kontaktinformasjon, anskaffelse av kjæledyr, oppussing eller andre bygningsmessige og/eller tekniske endringer.", "7. Kundens plikter", 1]])[0];
smart.push(smartDetail2);
const smartDetail3 = facts("gjensidigeHusSmartTerms", [["service.smart.utstyr", "Hus Smart – utstyr, retur og skylagring", "1.4 Utstyr Komponentene som er installert på Installasjonsadressen samt tilhørende tilbehør. Utstyret er Selskapets eiendom og Kunden har kun bruksrett i kontraktsperioden, med mindre annet er avtalt mellom Kunden og Selskapet. Dette gjelder også tilleggsutstyr. Tilleggsutstyr er Utstyr som kunden bestiller i tillegg til standardpakkene som følger med i Brann- og vannalarm og Innbruddsalarm. Ytterligere informasjon om det aktuelle Utstyret og Tjenestene vil bli gitt i forbindelse med installasjonen og angis også i informasjon som følger med Utstyret. Kunden har ikke anledning til å inkludere Utstyr til Alarmtjenesten som ikke har blitt bestilt fra Selskapet, med mindre dette er avtalt. Tilleggsutstyr kan bestilles direkte fra installatør ved Installasjon, eller ved å kontakte Selskapet på +47 915 03 100. Før kunden bestiller og tar i bruk tilleggskomponenter knyttet til innbrudd må kunden ha bestilt Innbruddsalarm. Se punkt 1.6. Komponenter knyttet til innbrudd inkluderer bevegelsesdetektor, bevegelsessensor med kamera, dør- og vindussensor og betjeningspanel. 1.7 Lagring av video i skytjeneste Skylagring er inkludert i 12 måneder, ved bestilling av ekstrautstyr som bruker skylagring, for eksempel videoringeklokke. Tjenesten leveres av Ajax og dekkes av Selskapet i denne perioden. Hvis Kunde ønsker å fortsette å bruke skylagring etter 12 måneder, eller etter at avtalen er avsluttet, må Kunde inngå en egen avtale for skylagring med Selskapet eller direkte med Ajax. Ved kontraktens opphør, har Selskapet rett til å få tilbake alt Utstyr og merking. Hvis Utstyret ikke er i driftsmessig stand, vil Kunden bli belastet for eventuelle reparasjonskostnader, eventuelt tapt Utstyr. Selskapet er ikke ansvarlig for merker eller skader som måtte oppstå som følge av demontering av Utstyr og merking. For Brann- og vannalarm er Kunden ansvarlig for å demontere og returnere Utstyret. Selskapet betaler for porto. Dersom Kunden har Innbruddsalarm kan Kunden i stedet be Selskapet nedmontere Utstyret. Kunden plikter å gi Selskapet tilgang til eiendommen mellom kl. 08.00 og 16.00 på hverdager for gjennomføring av frakoblings- og nedmonteringsarbeid. Dette gjelder også etter at Kunden eventuelt har flyttet fra Installasjonsadressen. Hvis frakobling og nedmontering ikke er mulig før opphør av kontrakten på grunn av Kundens forhold, kan Kunden bli belastet for tapt Utstyr, samt månedsabonnement og eventuelle merkostnader ved utløst alarm, samtaler med nødetatene, osv. frem til frakobling og nedmontering av Utstyret er gjennomført. Selskapet har under enhver omstendighet rett til tilgang til Installasjonsadressen utvendig for å fjerne merking, også uten Kundens tilstedeværelse, og er ikke ansvarlig for skade som kunne vært unngått ved Kundens medvirkning og tilstedeværelse. Ringeklokken er ikke en del av komponentene som leies gjennom forsikringen. Den er din når du kjøper den, og du beholder ringeklokken hvis du velger å avslutte forsikringen.", "1.4 Utstyr; 1.7 Lagring av video i skytjeneste; 10. Varighet og oppsigelse / Retur", 1]])[0];
