smart.push(smartDetail3);
const smartDetail4 = facts("gjensidigeHusSmartTerms", [["service.smart.oppsigelse", "Hus Smart – flytting og oppsigelse", "8. Flytting og overføring av kontrakten Hvis Kunden flytter fra Installasjonsadressen opphører denne Avtalen. Kunden kan etter avtale med Selskapet å overføre bruksretten til den nye eieren. Kunden må i tilfelle opplyse Selskapet om navn og kontaktopplysninger til den nye eieren, etter avtale med denne. Hvis Kunden ønsker å overføre Utstyret og Tjenestene til sitt nye hjem eller nye lokaler, må Kunden bestille Tjenestene til sitt nye hjem. Selskapet vil da håndtere overføring og installasjon på ny adresse, forutsatt at den nye adressen er i et område som dekkes av Selskapet og forutsatt at det er tilfredsstillende mobildekning på den nye adressen. 10. Varighet og oppsigelse Vilkårene trer i kraft ved inngåelse av denne Avtalen. Avtalen løper inntil den sies opp eller endres av en av Partene. Avtalen kan sies opp skriftlig av Selskapet med tre måneders varsel. Kunden har ingen oppsigelsesfrist dersom behovet for tjenesten er bortfalt eller dersom tjenesten skal flyttes til annet selskap. Ved flytting er oppsigelsesfristen 1 måned. Selskapet kan overdra hele eller deler av sin virksomhet, inkludert alle rettigheter og forpliktelser under denne avtalen, til et annet selskap uten forhåndsgodkjenning fra Kunden. Selskapet skal gi skriftlig varsel til Kunden før en slik overdragelse finner sted. Ved kontraktens opphør, har Selskapet rett til å få tilbake alt Utstyr og merking. Hvis Utstyret ikke er i driftsmessig stand, vil Kunden bli belastet for eventuelle reparasjonskostnader, eventuelt tapt Utstyr. Selskapet er ikke ansvarlig for merker eller skader som måtte oppstå som følge av demontering av Utstyr og merking. For Brann- og vannalarm er Kunden ansvarlig for å demontere og returnere Utstyret. Selskapet betaler for porto. Dersom Kunden har Innbruddsalarm kan Kunden i stedet be Selskapet nedmontere Utstyret. Kunden plikter å gi Selskapet tilgang til eiendommen mellom kl. 08.00 og 16.00 på hverdager for gjennomføring av frakoblings- og nedmonteringsarbeid. Dette gjelder også etter at Kunden eventuelt har flyttet fra Installasjonsadressen. Hvis frakobling og nedmontering ikke er mulig før opphør av kontrakten på grunn av Kundens forhold, kan Kunden bli belastet for tapt Utstyr, samt månedsabonnement og eventuelle merkostnader ved utløst alarm, samtaler med nødetatene, osv. frem til frakobling og nedmontering av Utstyret er gjennomført. Selskapet har under enhver omstendighet rett til tilgang til Installasjonsadressen utvendig for å fjerne merking, også uten Kundens tilstedeværelse, og er ikke ansvarlig for skade som kunne vært unngått ved Kundens medvirkning og tilstedeværelse.", "8. Flytting og overføring av kontrakten; 10. Varighet og oppsigelse", 1]])[0];
